<script setup lang="ts">
/**
 * 导入类型声明
 */
import type { CSSProperties } from 'vue';
import type { BaseIconName } from '@/types';

/**
 * 定义 props 的类型声明
 */
interface Props {
  /**
   * 自定义小图标名称；未传时展示默认线描空态 SVG 插画
   */
  icon?: BaseIconName;
  /**
   * 图标/插画颜色（支持任意 CSS 颜色值或主题变量）
   */
  color?: string;
  /**
   * 插画透明度（默认 0.45，避免在浅/深底上过抢眼）
   */
  opacity?: number;
  /**
   * SVG 插画宽度（px）；未传时常规 116px、紧凑态 78px
   */
  imageSize?: number;
  /**
   * 主空态文案
   */
  title?: string;
  /**
   * 可选辅助说明
   */
  description?: string;
  /**
   * 紧凑模式（用于侧栏列表、悬浮面板等小区域）
   */
  compact?: boolean;
}

/**
 * 定义 props
 */
const props = withDefaults(defineProps<Props>(), {
  icon: undefined,
  color: 'var(--color-text-muted)',
  opacity: 0.45,
  imageSize: undefined,
  title: '暂无数据',
  description: '',
  compact: false,
});

/**
 * 计算属性
 * 作用：控制插画颜色与尺寸
 */
const imageStyle = computed<CSSProperties>(() => {
  const size = props.imageSize ?? (props.compact ? 78 : 116);
  return {
    color: props.color,
    width: props.icon ? undefined : `${size}px`,
  };
});
</script>

